import datetime
from django.utils import timezone
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from knox.models import AuthToken

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def extend_device_session(request, token_id):
    try:
        # Require that the target token belongs to the requesting user
        token = AuthToken.objects.get(pk=token_id, user=request.user)
    except AuthToken.DoesNotExist:
        return Response({'detail': 'Token not found'}, status=status.HTTP_404_NOT_FOUND)

    days = min(int(request.data.get('extend_days', 14)), 30)
    token.expiry = timezone.now() + datetime.timedelta(days=days)
    token.save(update_fields=['expiry'])
    return Response({'token_id': token.id, 'new_expiry': token.expiry})
